std::span<const Byte> FindHarteSubset (const char * cpuType, Byte opcode)
{
    for (auto part : s_kParts)
    {
        for (const HarteSubsetEntry & entry : part())
        {
            if (entry.opcode == opcode && strcmp (entry.cpu, cpuType) == 0)
            {
                return std::span<const Byte> (entry.bytes, entry.size);
            }
        }
    }

    return std::span<const Byte>();
}
